    static class Grant {
        final String id;
        final String sku;
        int remaining;
        final int startDay;
        final int endDay;
        Grant(String id, String sku, int units, int startDay, int endDay) {
            this.id = id; this.sku = sku; this.remaining = units; this.startDay = startDay; this.endDay = endDay;
        }
    }
    static class Deny {
        final String sku;
        final int units;
        final int startDay;
        final int endDay;
        Deny(String sku, int units, int startDay, int endDay) {
            this.sku = sku; this.units = units; this.startDay = startDay; this.endDay = endDay;
        }
    }

    static List<Grant> grants = new ArrayList<>();
    static List<Deny> denies = new ArrayList<>();
    static Map<String, List<String>> tickets = new HashMap<>();
    static List<String> auditLog = new ArrayList<>();

    static void reset() { grants.clear(); denies.clear(); tickets.clear(); auditLog.clear(); }
    static void addGrant(String id, String sku, int units, int startDay, int endDay) { grants.add(new Grant(id, sku, units, startDay, endDay)); }
    static void addDeny(String sku, int units, int startDay, int endDay) { denies.add(new Deny(sku, units, startDay, endDay)); }
