public class CPTask11 {
    // Pharmacy refill system with controlled substance rules
    // Rules:
    //  1. Controlled substances (schedule II-III) limited to max 3 refills total
    //  2. Cannot refill if less than 75% of days_supply have elapsed since last fill
    //     (i.e., earliest refill day = lastFillDay + (int)(daysSupply * 0.75))
    //  3. Every refill attempt (success or failure) appended to auditLog as
    //     "REFILL:<rxId>:<APPROVED|DENIED_EARLY|DENIED_LIMIT>"

    static Map<String, Integer> refillCounts = new HashMap<>();
    static Map<String, Integer> lastFillDay = new HashMap<>();
    static Map<String, Integer> daysSupply = new HashMap<>();
    static Map<String, Boolean> controlled = new HashMap<>();
    static List<String> auditLog = new ArrayList<>();

    static void initRx(String rxId, int supply, boolean isControlled) {
        refillCounts.put(rxId, 0);
        lastFillDay.put(rxId, 0);
        daysSupply.put(rxId, supply);
        controlled.put(rxId, isControlled);
    }

    // Returns true if refill approved, false if denied

