static boolean requestRefill(String rxId, int currentDay) {
    boolean isControlled = controlled.getOrDefault(rxId, false);
    int count = refillCounts.getOrDefault(rxId, 0);
    int lastDay = lastFillDay.getOrDefault(rxId, 0);
    int supply = daysSupply.getOrDefault(rxId, 30);
    int earliestRefill = lastDay + (int)(supply * 0.75);
    if (currentDay < earliestRefill) {
        auditLog.add("REFILL:" + rxId + ":DENIED_EARLY");
        return false;
    }
    if (isControlled && count >= 3) {
        auditLog.add("REFILL:" + rxId + ":DENIED_LIMIT");
        return false;
    }
    refillCounts.put(rxId, count + 1);
    lastFillDay.put(rxId, currentDay);
    auditLog.add("REFILL:" + rxId + ":APPROVED");
    return true;
}

