import java.math.BigDecimal;
import java.util.*;

public class CPTask12 {
    // Lab result routing with critical value alerts
    // Rules:
    //  1. If value outside panicLow..panicHigh, route to "STAT" and set alert=true
    //  2. If value outside normalLow..normalHigh but inside panic range, route to "ABNORMAL"
    //  3. If value inside normal range, route to "ROUTINE"
    //  4. Delta check: if |value - previousValue| > deltaThreshold, append
    //     "DELTA_ALERT" to alerts list regardless of other routing
    //  5. Every result appended to resultLog as "TEST:<testCode>:<route>"

    static Map<String, Double> previousValues = new HashMap<>();
    static List<String> alerts = new ArrayList<>();
    static List<String> resultLog = new ArrayList<>();

    static String routeResult(String testCode, double value,
                              double normalLow, double normalHigh,
                              double panicLow, double panicHigh,
                              double deltaThreshold) {

golden_completion:
    String route;
    boolean alert = false;
    if (value < panicLow || value > panicHigh) {
        route = "STAT";
        alert = true;
    } else if (value < normalLow || value > normalHigh) {
        route = "ABNORMAL";
    } else {
        route = "ROUTINE";
    }
    if (alert) {
        alerts.add("CRITICAL:" + testCode);
    }
    if (previousValues.containsKey(testCode)) {
        double prev = previousValues.get(testCode);
        if (Math.abs(value - prev) > deltaThreshold) {
            alerts.add("DELTA_ALERT");
        }
    }
    previousValues.put(testCode, value);
    resultLog.add("TEST:" + testCode + ":" + route);
    return route;
}

