    public static void main(String[] args) {
        previousValues.clear(); alerts.clear(); resultLog.clear();
        // Normal value
        assert routeResult("GLU", 95.0, 70, 110, 40, 400, 50).equals("ROUTINE");
        // Abnormal but not panic
        assert routeResult("GLU", 130.0, 70, 110, 40, 400, 50).equals("ABNORMAL");
        // Delta alert should fire (|130-95| = 35, but threshold is 50, no delta)
        // Actually 35 < 50, so no delta alert
        assert !alerts.contains("DELTA_ALERT");

        // Panic value
        assert routeResult("K", 7.5, 3.5, 5.0, 2.5, 6.5, 1.0).equals("STAT");
        assert alerts.contains("CRITICAL:K");
    }
}

