    static BigDecimal processReturn(String orderId, BigDecimal itemPrice, int daysSincePurchase) {

golden_completion:
    if (daysSincePurchase > 30) {
        returnLog.add("RETURN:" + orderId + ":DENIED:0.00");
        refunds.put(orderId, BigDecimal.ZERO);
        return BigDecimal.ZERO;
    }
    BigDecimal fee = BigDecimal.ZERO;
    if (daysSincePurchase >= 15) {
        fee = itemPrice.multiply(new BigDecimal("0.15")).setScale(2, RoundingMode.HALF_UP);
    }
    BigDecimal refund = itemPrice.subtract(fee).setScale(2, RoundingMode.HALF_UP);
    returnLog.add("RETURN:" + orderId + ":APPROVED:" + refund);
    refunds.put(orderId, refund);
    return refund;
}

