        initClient("api-user", 3, 2, 1.0);  // 3 regular, 2 burst, 1 token/sec refill

        // Use all regular tokens at time 0
        assert request("api-user", 0) == true;   // token 3->2
        assert request("api-user", 0) == true;   // token 2->1
        assert request("api-user", 0) == true;   // token 1->0

        // Now uses burst tokens
        assert request("api-user", 0) == true;   // burst 2->1
        assert request("api-user", 0) == true;   // burst 1->0

        // All exhausted
        assert request("api-user", 0) == false;

        // After 2 seconds, refill 2 regular tokens
        assert request("api-user", 2.0) == true;   // refill 2, use 1 -> 1 left
        assert request("api-user", 2.0) == true;   // use 1 -> 0
        assert request("api-user", 2.0) == false;  // no more regular, burst still 0
    }
}

