    //  3. HALF_OPEN: allow up to probeLimit requests.
    //     If a probe succeeds, transition to CLOSED and reset failure count.
    //     If a probe fails, transition back to OPEN (reset the timeout timer).
    //  4. Log every attempt as "CB:<state>:<ALLOW|DENY>"

    static String state = "CLOSED";
    static int consecutiveFailures = 0;
    static int failureThreshold = 3;
    static long resetTimeoutMs = 5000;
    static int probeLimit = 1;
    static int probeCount = 0;
