        if (state.equals("HALF_OPEN")) { state = "CLOSED"; consecutiveFailures = 0; }
        consecutiveFailures = 0;
    }

    static void recordFailure(long currentTimeMs) {
        if (state.equals("HALF_OPEN")) { state = "OPEN"; openedAt = currentTimeMs; probeCount = 0; return; }
        consecutiveFailures++;
        if (consecutiveFailures >= failureThreshold) { state = "OPEN"; openedAt = currentTimeMs; }
    }

