import java.util.*;

public class CPTask24 {
    static Map<String, Set<String>> prerequisites = new HashMap<>();  // course -> required courses
    static Map<String, Integer> capacity = new HashMap<>();           // course -> max seats
    static Map<String, List<String>> enrolled = new HashMap<>();      // course -> enrolled student IDs
    static Map<String, LinkedList<String>> waitlist = new HashMap<>(); // course -> waitlisted student IDs
    static Map<String, Set<String>> completed = new HashMap<>();      // student -> completed courses
    static List<String> enrollLog = new ArrayList<>();

    static void reset() {
        prerequisites.clear(); capacity.clear(); enrolled.clear();
        waitlist.clear(); completed.clear(); enrollLog.clear();
    }

    // Enroll a student in a course.
    // Rules:
    //   1. Check prerequisites: student must have completed ALL prerequisite courses.
    //      If not met, log "PREREQ_FAIL:<student>:<course>" and return "PREREQ_FAIL"
    //   2. Check duplicate: if student already enrolled OR on waitlist,
    //      log "DUPLICATE:<student>:<course>" and return "DUPLICATE"
    //   3. If seats available (enrolled.size < capacity), add to enrolled list,
    //      log "ENROLLED:<student>:<course>" and return "ENROLLED"
    //   4. Otherwise add to waitlist (FIFO),
    //      log "WAITLISTED:<student>:<course>" and return "WAITLISTED"
    static String enroll(String student, String course) {

