Set<String> prereqs = prerequisites.getOrDefault(course, Collections.emptySet());
Set<String> done = completed.getOrDefault(student, Collections.emptySet());
if (!done.containsAll(prereqs)) {
    enrollLog.add("PREREQ_FAIL:" + student + ":" + course);
    return "PREREQ_FAIL";
}
List<String> enrolledList = enrolled.computeIfAbsent(course, k -> new ArrayList<>());
LinkedList<String> wl = waitlist.computeIfAbsent(course, k -> new LinkedList<>());
if (enrolledList.contains(student) || wl.contains(student)) {
    enrollLog.add("DUPLICATE:" + student + ":" + course);
    return "DUPLICATE";
}
int cap = capacity.getOrDefault(course, Integer.MAX_VALUE);
if (enrolledList.size() < cap) {
    enrolledList.add(student);
    enrollLog.add("ENROLLED:" + student + ":" + course);
    return "ENROLLED";
}
wl.add(student);
enrollLog.add("WAITLISTED:" + student + ":" + course);
return "WAITLISTED";

suffix:
    }

    public static void main(String[] args) {
        reset();
        capacity.put("CS201", 2);
        prerequisites.put("CS201", new HashSet<>(Arrays.asList("CS101")));
        completed.put("Alice", new HashSet<>(Arrays.asList("CS101")));
        completed.put("Bob", new HashSet<>(Arrays.asList("CS101")));
        completed.put("Charlie", new HashSet<>(Arrays.asList("CS101")));

        assert enroll("Alice", "CS201").equals("ENROLLED");
        assert enroll("Bob", "CS201").equals("ENROLLED");
        assert enroll("Charlie", "CS201").equals("WAITLISTED");
        assert enrolled.get("CS201").size() == 2;
        assert waitlist.get("CS201").size() == 1;
    }
}

