import java.util.*;

public class CPTask26 {
    static class Job {
        final String id;
        final String productType;
        final int duration; // minutes
        final int priority; // lower = higher priority

        Job(String id, String productType, int duration, int priority) {
            this.id = id; this.productType = productType;
            this.duration = duration; this.priority = priority;
        }
    }

    static int machineAvailableFrom;  // start of available window (minutes from midnight)
    static int machineAvailableUntil; // end of available window
    static int setupTime;             // setup minutes when switching product types
    static List<String> scheduleLog = new ArrayList<>();

    static void reset() { scheduleLog.clear(); }

    // Schedule jobs on a single machine within the availability window.
    // Rules:
    //   1. Sort jobs by priority (ascending — lower number = higher priority)
    //   2. Start scheduling at machineAvailableFrom
    //   3. When switching product types (current != previous), add setupTime
    //      (first job has no setup penalty)
    //   4. If a job fits entirely within the window, schedule it:
    //      Log "SCHEDULED:<jobId>:<startTime>-<endTime>"
    //   5. If a job does NOT fit, skip it:
    //      Log "SKIPPED:<jobId>:INSUFFICIENT_TIME"
    //   6. Return total number of jobs scheduled
    static int scheduleJobs(List<Job> jobs) {

golden_completion:
List<Job> sorted = new ArrayList<>(jobs);
sorted.sort(Comparator.comparingInt(j -> j.priority));
int currentTime = machineAvailableFrom;
String lastProductType = null;
int scheduled = 0;
for (Job job : sorted) {
    int start = currentTime;
    if (lastProductType != null && !lastProductType.equals(job.productType)) {
        start += setupTime;
    }
    int end = start + job.duration;
    if (end <= machineAvailableUntil) {
        scheduleLog.add("SCHEDULED:" + job.id + ":" + start + "-" + end);
        currentTime = end;
        lastProductType = job.productType;
        scheduled++;
    } else {
        scheduleLog.add("SKIPPED:" + job.id + ":INSUFFICIENT_TIME");
    }
}
return scheduled;

suffix:
    }

    public static void main(String[] args) {
        reset();
        machineAvailableFrom = 480;  // 8:00 AM
        machineAvailableUntil = 600; // 10:00 AM (120 min window)
        setupTime = 10;

        List<Job> jobs = Arrays.asList(
            new Job("J1", "TypeA", 30, 2),
            new Job("J2", "TypeA", 30, 1),
            new Job("J3", "TypeB", 40, 3)
        );
        int count = scheduleJobs(jobs);
        // Priority order: J2(1), J1(2), J3(3)
        // J2: TypeA, start=480, end=510 (scheduled)
        // J1: TypeA same type, start=510, end=540 (scheduled)
        // J3: TypeB switch, start=540+10=550, end=590 (scheduled, 590<=600)
        assert count == 3 : "Expected 3 scheduled, got " + count;
        assert scheduleLog.get(0).equals("SCHEDULED:J2:480-510") : "Log[0]: " + scheduleLog.get(0);
        assert scheduleLog.get(1).equals("SCHEDULED:J1:510-540") : "Log[1]: " + scheduleLog.get(1);
        assert scheduleLog.get(2).equals("SCHEDULED:J3:550-590") : "Log[2]: " + scheduleLog.get(2);
    }
}

