public class CPTask27 {
    enum EscrowStatus { OPEN, CONTINGENCY_FAILED, CLOSED, FORFEITED }

    static class Contingency {
        final String name;
        final int deadlineDay;   // day number by which it must be satisfied
        boolean satisfied;

        Contingency(String name, int deadlineDay) {
            this.name = name; this.deadlineDay = deadlineDay; this.satisfied = false;
        }
    }

    static EscrowStatus status;
    static BigDecimal earnestMoney;
    static BigDecimal forfeitedAmount;
    static List<Contingency> contingencies;  // must be processed in deadline order
    static List<String> escrowLog = new ArrayList<>();

    static void reset() {
        status = EscrowStatus.OPEN; forfeitedAmount = BigDecimal.ZERO;
        escrowLog.clear();
    }

    // Process contingencies up to the given currentDay.
    // Rules:
    //   1. Process contingencies in DEADLINE ORDER (earliest first)
    //   2. Skip contingencies whose deadline is after currentDay (not yet due)
    //   3. If a contingency is due (deadlineDay <= currentDay) and NOT satisfied:
    //      - Set status to CONTINGENCY_FAILED
    //      - Forfeit earnest money: forfeitedAmount = earnestMoney
    //      - Log "FAILED:<name>:DAY<deadlineDay>:FORFEITED:<earnestMoney>"
    //      - Stop processing further contingencies (first failure stops escrow)
    //   4. If contingency is due AND satisfied, log "CLEARED:<name>:DAY<deadlineDay>"
    //   5. If ALL due contingencies are satisfied, status stays OPEN
    // Returns the current EscrowStatus
    static EscrowStatus processContingencies(int currentDay) {

golden_completion:
