sorted.sort(Comparator.comparingInt(c -> c.deadlineDay));
for (Contingency c : sorted) {
    if (c.deadlineDay > currentDay) continue;
    if (!c.satisfied) {
        status = EscrowStatus.CONTINGENCY_FAILED;
        forfeitedAmount = earnestMoney;
        escrowLog.add("FAILED:" + c.name + ":DAY" + c.deadlineDay + ":FORFEITED:" + earnestMoney);
        return status;
    }
    escrowLog.add("CLEARED:" + c.name + ":DAY" + c.deadlineDay);
}
return status;

suffix:
    }

