        // Pairs: Alice vs Bob, Charlie vs Diana
        List<String> adv = generateFirstRound(players);
        assert adv.size() == 2 : "Expected 2 advancing, got " + adv.size();
        assert adv.contains("Alice") : "Alice (seed 1) should advance";
