    if (adj.compareTo(BigDecimal.ZERO) < 0) adjBill = adjBill.negate();
    totalBilled = totalBilled.add(adjBill);
    auditLog.add("ADJUST:" + adj + ":BILL:" + adjBill);
    estimatedUsage = BigDecimal.ZERO;
} else { totalBilled = totalBilled.add(calculateBill(actualUsage)); }
lastActualReading = reading; lastBilledReading = reading; estimateCount = 0;
auditLog.add("ACTUAL:" + reading + ":USAGE:" + actualUsage);
return totalBilled;

