import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask39 {
    static Map<String, BigDecimal> baseRecipe = new LinkedHashMap<>();
    static Map<String, String> substitutions = new HashMap<>();
    static Map<String, BigDecimal> substitutionRatios = new HashMap<>();
    static BigDecimal minAmount = new BigDecimal("0.25");
    static int baseServings = 4;
    static List<String> auditLog = new ArrayList<>();

    static {
        baseRecipe.put("flour", new BigDecimal("2.00"));
        baseRecipe.put("sugar", new BigDecimal("1.00"));
        baseRecipe.put("butter", new BigDecimal("0.50"));
        baseRecipe.put("eggs", new BigDecimal("3.00"));
        baseRecipe.put("milk", new BigDecimal("1.00"));
        substitutions.put("butter", "oil");
        substitutionRatios.put("oil", new BigDecimal("0.75"));
        substitutions.put("milk", "oat_milk");
        substitutionRatios.put("oat_milk", new BigDecimal("1.00"));
    }

    // Scale recipe to targetServings with substitutions applied. Rules:
    // 1. scaleFactor = targetServings / baseServings (use BigDecimal division, scale 4, HALF_UP)
    // 2. For each ingredient in baseRecipe:
    //    a. scaledAmount = baseAmount * scaleFactor (scale 2, HALF_UP)
    //    b. If ingredient has a substitution, apply ratio: finalAmount = scaledAmount * ratio (scale 2, HALF_UP)
    //       Use the substitute name as the key
    //    c. If finalAmount < minAmount, set to minAmount
    //    d. Log "SCALE:<ingredientOrSubstitute>:<finalAmount>"
    // 3. Return the final recipe as LinkedHashMap (preserving insertion order)
    static Map<String, BigDecimal> scaleRecipe(int targetServings) {

golden_completion:
Map<String, BigDecimal> result = new LinkedHashMap<>();
BigDecimal scaleFactor = new BigDecimal(targetServings)
    .divide(new BigDecimal(baseServings), 4, RoundingMode.HALF_UP);
for (Map.Entry<String, BigDecimal> entry : baseRecipe.entrySet()) {
    String ingredient = entry.getKey();
    BigDecimal scaledAmount = entry.getValue().multiply(scaleFactor).setScale(2, RoundingMode.HALF_UP);
    String finalName = ingredient;
    BigDecimal finalAmount = scaledAmount;
    if (substitutions.containsKey(ingredient)) {
        finalName = substitutions.get(ingredient);
        finalAmount = scaledAmount.multiply(substitutionRatios.get(finalName)).setScale(2, RoundingMode.HALF_UP);
    }
    if (finalAmount.compareTo(minAmount) < 0) finalAmount = minAmount;
    result.put(finalName, finalAmount);
    auditLog.add("SCALE:" + finalName + ":" + finalAmount);
}
return result;

suffix:
    }

    public static void main(String[] args) {
        auditLog.clear();
        Map<String, BigDecimal> recipe = scaleRecipe(8);
        // scaleFactor = 8/4 = 2.0
        // flour: 2*2 = 4.00, sugar: 1*2 = 2.00, butter->oil: 0.5*2*0.75 = 0.75
        // eggs: 3*2 = 6.00, milk->oat_milk: 1*2*1.0 = 2.00
        assert recipe.get("flour").compareTo(new BigDecimal("4.00")) == 0 : "Flour should be 4.00";
        assert recipe.get("oil").compareTo(new BigDecimal("0.75")) == 0 : "Oil should be 0.75";
        assert recipe.get("oat_milk").compareTo(new BigDecimal("2.00")) == 0 : "Oat milk should be 2.00";
        assert !recipe.containsKey("butter") : "Butter should be substituted";
        assert !recipe.containsKey("milk") : "Milk should be substituted";
    }
}

