import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask40 {
    static BigDecimal dangerZoneLow = new BigDecimal("40");
    static BigDecimal dangerZoneHigh = new BigDecimal("140");
    static int maxDangerMinutes = 120;
    static int consecutiveViolationLimit = 3;
    static int totalDangerMinutes;
    static int consecutiveViolations;
    static String foodStatus;
    static List<String> auditLog;
    static List<BigDecimal> tempHistory;

    static void init() {
        totalDangerMinutes = 0;
        consecutiveViolations = 0;
        foodStatus = "SAFE";
        auditLog = new ArrayList<>();
        tempHistory = new ArrayList<>();
    }

    // Record temperature check. Rules:
    // 1. If foodStatus is DISCARD, return "DISCARDED" (no further changes)
    // 2. Add temp to tempHistory
    // 3. Determine if temp is in danger zone: dangerZoneLow < temp < dangerZoneHigh
    //    (exactly at boundaries is SAFE: <=40 or >=140 is safe)
    // 4. If in danger zone:
    //    a. totalDangerMinutes += minutesSinceLastCheck
    //    b. consecutiveViolations++
    //    c. If consecutiveViolations >= consecutiveViolationLimit:
    //       foodStatus = "DISCARD", log "DISCARD:CONSECUTIVE:<consecutiveViolations>"
    //       return "DISCARDED"
    //    d. If totalDangerMinutes >= maxDangerMinutes:
    //       foodStatus = "DISCARD", log "DISCARD:TIME:<totalDangerMinutes>"
    //       return "DISCARDED"
    //    e. foodStatus = "WARNING", log "WARNING:<temp>:DANGER_MIN:<totalDangerMinutes>"
    // 5. If safe (not in danger zone):
    //    a. consecutiveViolations = 0 (reset on safe reading)
    //    b. foodStatus = "SAFE"
    //    c. log "SAFE:<temp>"
    // 6. Return foodStatus
    static String recordTemp(BigDecimal temp, int minutesSinceLastCheck) {

golden_completion:
if (foodStatus.equals("DISCARD")) return "DISCARDED";
tempHistory.add(temp);
boolean inDanger = temp.compareTo(dangerZoneLow) > 0 && temp.compareTo(dangerZoneHigh) < 0;
if (inDanger) {
    totalDangerMinutes += minutesSinceLastCheck;
    consecutiveViolations++;
    if (consecutiveViolations >= consecutiveViolationLimit) {
        foodStatus = "DISCARD";
        auditLog.add("DISCARD:CONSECUTIVE:" + consecutiveViolations);
        return "DISCARDED";
    }
    if (totalDangerMinutes >= maxDangerMinutes) {
        foodStatus = "DISCARD";
        auditLog.add("DISCARD:TIME:" + totalDangerMinutes);
        return "DISCARDED";
    }
    foodStatus = "WARNING";
    auditLog.add("WARNING:" + temp + ":DANGER_MIN:" + totalDangerMinutes);
} else {
    consecutiveViolations = 0;
    foodStatus = "SAFE";
    auditLog.add("SAFE:" + temp);
}
return foodStatus;

suffix:
    }

    public static void main(String[] args) {
        init();
        // Safe reading at boundary
        String r1 = recordTemp(new BigDecimal("140"), 0);
        assert r1.equals("SAFE") : "140F should be safe, got " + r1;

        // Danger zone reading
        String r2 = recordTemp(new BigDecimal("80"), 30);
        assert r2.equals("WARNING") : "80F should be warning, got " + r2;
        assert totalDangerMinutes == 30 : "Should have 30 danger minutes";
        assert consecutiveViolations == 1;

        // Back to safe - resets consecutive
        String r3 = recordTemp(new BigDecimal("160"), 15);
        assert r3.equals("SAFE") : "160F should be safe, got " + r3;
        assert consecutiveViolations == 0 : "Consecutive should reset";
    }
}

