import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask44 {
    // Policy renewal rules:
    // 1. Policy states: ACTIVE, GRACE, LAPSED, CANCELLED
    // 2. If currentDay <= expiryDay and policyState is ACTIVE, return "ALREADY_ACTIVE"
    // 3. Days past expiry = max(0, currentDay - expiryDay)
    // 4. 0-30 days past: GRACE renewal — restore to ACTIVE at base premium, new expiry = currentDay + 365
    // 5. 31-90 days past: PENALTY renewal — ACTIVE, but premium + 25% + $75 reinstatement fee
    // 6. 91+ days past: LAPSED — cannot renew
    // 7. Audit log: "RENEWED:<policyId>:$<totalCost>" or "LAPSED:<policyId>"

    static String policyState = "ACTIVE";
    static int expiryDay = 100;
    static BigDecimal basePremium = new BigDecimal("400.00");
    static List<String> auditLog = new ArrayList<>();

    static String renewPolicy(String policyId, int currentDay) {

golden_completion:
if (policyState.equals("ACTIVE") && currentDay <= expiryDay) {
    return "ALREADY_ACTIVE";
}
int daysPastExpiry = currentDay - expiryDay;
if (daysPastExpiry < 0) daysPastExpiry = 0;

if (daysPastExpiry <= 30) {
    policyState = "ACTIVE";
    expiryDay = currentDay + 365;
    auditLog.add("RENEWED:" + policyId + ":$" + basePremium.setScale(2, RoundingMode.HALF_UP));
    return "RENEWED";
} else if (daysPastExpiry <= 90) {
    BigDecimal penalty = basePremium.multiply(new BigDecimal("0.25"));
    BigDecimal total = basePremium.add(penalty).add(new BigDecimal("75.00")).setScale(2, RoundingMode.HALF_UP);
    policyState = "ACTIVE";
    expiryDay = currentDay + 365;
    auditLog.add("RENEWED:" + policyId + ":$" + total);
    return "RENEWED";
} else {
    policyState = "LAPSED";
    auditLog.add("LAPSED:" + policyId);
    return "LAPSED";
}

suffix:
    }

    public static void main(String[] args) {
        // Before expiry — already active
        assert renewPolicy("POL-1", 50).equals("ALREADY_ACTIVE");

        // Day 110 — 10 days past expiry, within grace → renew at base $400
        policyState = "ACTIVE";
        expiryDay = 100;
        String r1 = renewPolicy("POL-1", 110);
        assert r1.equals("RENEWED") : r1;
        assert policyState.equals("ACTIVE");
        assert auditLog.get(0).equals("RENEWED:POL-1:$400.00") : auditLog.get(0);
    }
}

