import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask45 {
    // Usage metering rules:
    // 1. Committed tier: first 1000 units included in base fee ($200)
    // 2. Overage: units 1001-2000 at $0.30/unit; units 2001+ at $0.50/unit (burst pricing)
    // 3. Running usage accumulates across recordUsage() calls within a billing period
    // 4. closeBillingPeriod() calculates total bill, resets usage to 0, returns the bill
    // 5. Minimum charge: bill cannot be below $200 (the base fee) even with credits
    // 6. Audit log: "USAGE:<units>:running=<total>" per record, "BILL:$<amount>" on close

    static int currentUsage = 0;
    static BigDecimal credits = BigDecimal.ZERO;
    static List<String> auditLog = new ArrayList<>();

    static void recordUsage(int units) {
        currentUsage += units;
        auditLog.add("USAGE:" + units + ":running=" + currentUsage);
    }

    static BigDecimal closeBillingPeriod() {

golden_completion:
