BigDecimal overage = BigDecimal.ZERO;
if (currentUsage > 2000) {
    overage = new BigDecimal("1000").multiply(new BigDecimal("0.30"))
        .add(new BigDecimal(currentUsage - 2000).multiply(new BigDecimal("0.50")));
} else if (currentUsage > 1000) {
    overage = new BigDecimal(currentUsage - 1000).multiply(new BigDecimal("0.30"));
}
BigDecimal total = baseFee.add(overage).subtract(credits).setScale(2, RoundingMode.HALF_UP);
