    public static void main(String[] args) {
        // Season 1: 15 goals, 30 games — $100K bonus but escrowed
        recordSeason(15, 30);
        // Paid: $2M salary only (bonus escrowed)
        assert totalPaid.compareTo(new BigDecimal("2000000.00")) == 0 : "S1 paid: " + totalPaid;
        assert escrow.compareTo(new BigDecimal("100000.00")) == 0 : "S1 escrow: " + escrow;

        // Season 2: 25 goals, 35 games — $300K bonus but escrowed
        recordSeason(25, 35);
        assert totalPaid.compareTo(new BigDecimal("4000000.00")) == 0 : "S2 paid: " + totalPaid;
        assert escrow.compareTo(new BigDecimal("400000.00")) == 0 : "S2 escrow: " + escrow;

        // Season 3: 22 goals, 38 games — $300K bonus + escrow release ($400K) = $700K paid
        recordSeason(22, 38);
        assert vested : "Should be vested after season 3";
        // S3: 2M + 300K + 400K escrow = 2.7M; total = 4M + 2.7M = 6.7M
        assert totalPaid.compareTo(new BigDecimal("6700000.00")) == 0 : "S3 total: " + totalPaid;
    }
}

